  ("año", numero, pregunta, opcion_a, opcion_b, opcion_c, opcion_d, opcion_e, correcta, imagen_path, tema, explicacion_calidad)
VALUES
  (2023, 1, 'Teniendo en cuenta la relación estructura-actividad general de los agentes neurolépticos derivados de butirofenona, ¿cuál de las modificaciones propuestas conduciría a compuestos más activos?:', 'Sustitución del grupo carbonilo B por un tiocarbonilo.', 'Eliminación del átomo de flúor en el anillo aromático A.', 'Introducción de un anillo de piperidina, tetrahidropiridina o piperazina sustituidos como fragmento D.', 'Alargamiento de la cadena C.', NULL, 'c', NULL, NULL, NULL),
  (2023, 2, 'La siguiente reacción es un proceso de semisíntesis para la obtención de derivados de bases nitrogenadas. ¿Qué producto resultará de la siguiente secuencia de reacciones?:', 'Adenina.', 'Guanina.', '8-amino-9H-purina.', '2-amino-9H-purin-8-ol.', NULL, 'b', NULL, NULL, 'sin_imagen'),
  (2023, 3, '¿Qué representa el símbolo 𝝅 (pi) en una ecuación QSAR (Quantitative Structure Activity Relationship) de tipo Hansch-Fujita?:', 'El coeficiente de partición octanol/agua de la molécula.', 'Los efectos electrónicos de un sustituyente.', 'Los efectos estéricos de un sustituyente.', 'La constante de hidrofobicidad de un sustituyente.', NULL, 'd', NULL, NULL, NULL),
  (2023, 4, 'Un compuesto inactivo que necesita ser activado por procesos metabólicos para tener efecto terapéutico, se denomina:', 'Fármaco huérfano.', 'Fármaco bioequivalente.', 'Profármaco.', 'Antimetabolito.', NULL, 'c', NULL, NULL, NULL),
  (2023, 5, '¿Cuál de los siguientes grupos funcionales se considera bioisóstero del grupo carboxílico?:', 'Grupo nitrilo.', 'Tetrazol.', 'Tiofeno.', 'Fenol.', NULL, 'b', NULL, NULL, NULL),
  (2023, 6, '¿Qué efecto tiene en la actividad de las 1,4benzodiazepinas la presencia de un grupo hidroxilo en la posición C-3, frente a su análogo sin hidroxilar?:', 'Conduce a compuestos que se eliminan más rápidamente.', 'Conduce a compuestos de vida media más larga.', 'Conduce a compuestos antagonistas del GABA.', 'Conduce a compuestos sin actividad ansiolítica.', NULL, 'a', NULL, NULL, NULL),
  (2023, 7, 'La conjugación con aminoácidos es una reacción metabólica de fase II. ¿Sobre cuál de los siguientes grupos puede tener lugar la reacción?:', 'Ácidos carboxílicos activados como tioésteres.', 'Aminas primarias aromáticas.', 'Fenoles.', 'Hidroxilaminas aromáticas, procedentes de la reducción del correspondiente nitroderivado.', NULL, 'a', NULL, NULL, NULL),
  (2023, 8, 'La hidrólisis de la amida en la posición 7 de la cefalosporina C permite obtener el ácido 7aminocefalosporánico (7-ACA). Para ello, una vez protegido el grupo ácido carboxílico de la cefalosporina, se trata con pentacloruro de fósforo y después con metanol. ¿En qué grupo sensible a la hidrólisis se ha convertido la amida de la posición 7?:', 'Enamina.', 'Cloruro de ácido.', 'Hemiacetal.', 'Iminoéter.', NULL, 'd', NULL, NULL, NULL),
  (2023, 9, 'La siguiente estructura corresponde al antitumoral mitomicina C. ¿Cuál es el paso inicial del proceso de activación de la mitomicina C que la convierte en un agente alquilante?:', 'Apertura del anillo de aziridina.', 'Hidrólisis del carbamato.', 'Formación de una enamina por pérdida de metanol.', 'Reducción del anillo de quinona.', NULL, 'd', NULL, NULL, NULL),
  (2023, 10, '¿Qué relación tiene el siguiente compuesto con el neuroléptico flufenazina?:', 'Es un análogo que establece interacciones adicionales con el receptor y prolonga su acción neuroléptica.', 'Es un profármaco más lipófilo para su uso en tratamientos prolongados.', 'Es un análogo blando que se metaboliza por hidrólisis de una manera predecible.', 'Es un análogo de acción corta porque la cadena voluminosa dificulta su unión al receptor.', NULL, 'b', NULL, NULL, 'sin_imagen'),
  (2023, 11, '¿Qué relación tiene la isoguvacina con el GABA (ácido gamma-aminobutírico)?:', 'Es un isóstero.', 'Es un homólogo.', 'Es un análogo rígido.', 'Es un vinílogo.', NULL, 'c', NULL, NULL, NULL),
  (2023, 12, '¿Qué tipo de interacción se establece entre el grupo fenólico de la molécula de morfina y el receptor opioide?:', 'Enlace iónico.', 'Enlace de hidrógeno.', 'Interacción pi-catión.', 'Interacción dipolo-dipolo.', NULL, 'b', NULL, NULL, NULL),
  (2023, 13, '¿Cuál de las siguientes afirmaciones en relación con el antioxidante natural ácido ascórbico es correcta?:', 'Es un antioxidante preventivo por su efecto quelante.', 'Es un antioxidante preventivo como agente que absorbe en el UV.', 'Es un antioxidante estabilizador de membranas.', 'Es un antioxidante captador de radicales.', NULL, 'd', NULL, NULL, NULL),
  (2023, 14, 'La acción antitumoral de la dacarbazina se debe a la formación de:', 'Una sal de metildiazonio.', 'Un catión aziridinio.', 'Un radical hidroxilo.', 'Una quinonimina.', NULL, 'a', NULL, NULL, NULL),
  (2023, 15, '¿Cuál de las siguientes afirmaciones sobre el mecanismo de acción de las antraciclinas NO es correcta?:', 'Son agentes intercalantes del ADN.', 'Generan radicales hidroxilo.', 'Son agentes quelantes.', 'Se unen al sitio A de la subunidad 30S del ribosoma.', NULL, 'd', NULL, NULL, NULL),
  (2023, 16, '¿Con qué molécula endógena guarda relación estructural el siguiente fármaco?:', 'Es un agonista del receptor de encefalinas.', 'Es un agonista del receptor de GABA.', 'Es un antagonista del receptor de angiotensina II.', 'Es un antagonista de receptores de ADP.', NULL, 'c', NULL, NULL, 'sin_imagen'),
  (2023, 17, '¿Cuál de las siguientes manipulaciones estructurales incrementa la acción anabólica de las hormonas masculinas?:', 'Introducción de un hidroxilo en la posición 11β.', 'Sustitución del carbono 2 por oxígeno.', 'Aromatización del anillo A.', 'Introducción de un metilo en la posición 16α.', NULL, 'b', NULL, NULL, NULL),
  (2023, 18, '¿Cuál de las siguientes estrategias aumentará la solubilidad en agua de una molécula candidata a fármaco?:', 'La introducción de un grupo hidroxilo.', 'La sustitución de un grupo hidroxilo por un metilo.', 'La reducción de un grupo cetona a alcano.', 'La introducción de un anillo aromático.', NULL, 'a', NULL, NULL, NULL),
  (2023, 19, '¿Cuál de los siguientes antibióticos betalactámicos NO tiene actividad frente a Pseudomonas aeruginosa?:', 'Cefepime.', 'Ceftolozano-tazobactam.', 'Meropenem.', 'Ertapenem.', NULL, 'd', NULL, NULL, NULL),
  (2023, 20, 'Para generar una infección, los dermatofitos necesitan afectar a un tejido rico en:', 'Hemoglobina.', 'Colágeno.', 'Queratina.', 'Ácido hialurónico.', NULL, 'c', NULL, NULL, NULL),
  (2023, 21, 'El marcador 1-3-beta-D-glucano se eleva en suero en las siguientes infecciones EXCEPTO en:', 'Aspergilosis invasiva.', 'Candidiasis hepatoesplénica.', 'Mucormicosis rinocerebral.', 'Neumonía causada por Pneumocystis jirovecii.', NULL, 'c', NULL, NULL, NULL),
  (2023, 22, '¿Cuál de las siguientes características corresponde a Campylobacter?:', 'Es un microorganismo cuyo reservorio es exclusivamente humano.', 'Es un bacilo grampositivo.', 'Produce diarrea asociada al consumo de carne de ave poco cocinada.', 'En la actualidad se dispone de una vacuna eficaz para prevenir la infección que causa.', NULL, 'c', NULL, NULL, NULL),
  (2023, 23, '¿Cuál de las infecciones causadas por uno de los siguientes microorganismos NO puede tratarse con penicilina?:', 'Treponema pallidum.', 'Streptococcus pyogenes.', 'Mycoplasma pneumoniae.', 'Streptococcus agalactiae.', NULL, 'c', NULL, NULL, NULL),
  (2023, 24, 'En relación con la sífilis, señale la respuesta FALSA:', 'El tratamiento de elección es colistina.', 'El agente etiológico es Treponema pallidum.', 'Es una infección de transmisión sexual.', 'En fase avanzada puede afectar al sistema nervioso central.', NULL, 'a', NULL, NULL, NULL),
  (2023, 25, 'En el cultivo de una muestra de líquido cefalorraquídeo, tras 24 horas de incubación a 35 ºC, se observa crecimiento en agar chocolate y en agar sangre, pero no en agar MacConkey. Las colonias crecidas son mucosas, alfa-hemolíticas, catalasa negativa, y presentan sensibilidad a la optoquina. ¿Cuál sería el microorganismo más probable?:', 'Streptococcus pneumoniae.', 'Klebsiella pneumoniae.', 'Escherichia coli.', 'Staphylococcus aureus.', NULL, 'a', NULL, NULL, NULL),
  (2023, 26, 'Señale la afirmación INCORRECTA respecto a Clostridioides difficile:', 'Es un bacilo grampositivo formador de esporas.', 'Es anaerobio obligado.', 'El tratamiento de elección de las infecciones que causa es vancomicina intravenosa.', 'Existen cepas epidémicas que han causado brotes y se asocian a mayor gravedad y mortalidad.', NULL, 'c', NULL, NULL, NULL),
  (2023, 27, '¿Cuál de las siguientes respuestas es correcta respecto al virus SARS-CoV-2?:', 'Es un virus ARN bicatenario de simetría helicoidal.', 'Reconoce el receptor humano ACE2 (enzima convertidora de angiotensina 2).', 'El gen estructural S es idéntico al del virus SARS-CoV-1.', 'Pertenece a la familia Orthomyxoviridae.', NULL, 'b', NULL, NULL, NULL),
  (2023, 29, '¿Cuál(es) de los siguientes agentes etiológicos de endocarditis NO se podría(n) detectar mediante el método de hemocultivos?:', 'Staphylococcus aureus.', 'Bartonella spp.', 'Streptococcus viridans.', 'Aggregatibacter spp.', NULL, 'b', NULL, NULL, NULL),
  (2023, 30, '¿Cuál de las siguientes afirmaciones es correcta en cuanto al diagnóstico microbiológico de Legionella pneumophila?:', 'El medio de cultivo que se suele usar para su aislamiento es el agar BCYE (agar tamponado con carbón activado y extracto de levadura).', 'Los inmunoanálisis se emplean para detectar antígenos lipopolisacáridos específicos de Legionella de todos los serogrupos excretados en la orina de los pacientes afectados.', 'En la tinción de Gram aparecen como bacilos grampositivos finos y pleomorfos teñidos de forma débil.', 'Para su crecimiento necesitan medios de cultivo carentes de L-cisteína.', NULL, 'a', NULL, NULL, NULL),
  (2023, 31, '¿Cuál de las siguientes asociaciones NO es correcta?:', 'Infección de quemaduras-Pseudomonas aeruginosa.', 'Infección por mordedura-Eikenella corrodens.', 'Fascitis necrosante-Streptococcus pyogenes.', 'Impétigo-Clostridioides difficile.', NULL, 'd', NULL, NULL, NULL),
  (2023, 32, '¿Cuál de las siguientes afirmaciones es correcta con respecto a Listeria monocytogenes?:', 'Son bacilos gramnegativos.', 'En agar sangre de cordero muestran βhemólisis.', 'Son anaerobios estrictos.', 'Da positiva la prueba de la oxidasa.', NULL, 'b', NULL, NULL, NULL),
  (2023, 33, '¿Cuál de los siguientes métodos empleados para estudiar la susceptibilidad de un microorganismo frente a un antimicrobiano NO es un método cuantitativo?:', 'Microdilución en caldo.', 'Tira de gradiente de concentración.', 'Macrodilución en caldo.', 'Método de Kirby-Bauer.', NULL, 'd', NULL, NULL, NULL),
  (2023, 34, '¿Qué factor (o factores) requiere Haemophilus influenzae para crecer en cultivo?:', 'Factores V y X.', 'Factores V y IX.', 'Factores IX y X.', 'Sólo factor V.', NULL, 'a', NULL, NULL, NULL),
  (2023, 35, 'Señale la respuesta correcta con respecto al género Nocardia:', 'Son bacterias anaerobias estrictas.', 'En la tinción de Gram se suelen ver como bacilos gramnegativos finos y ramificados.', 'Son parcialmente ácido-alcohol resistentes.', 'Son bacterias capsuladas.', NULL, 'c', NULL, NULL, NULL),
  (2023, 36, '¿Cuál de las siguientes enfermedades infecciosas es una zoonosis?:', 'Legionelosis.', 'Leptospirosis.', 'Tosferina.', 'Enfermedad de Whipple.', NULL, 'b', NULL, NULL, NULL),
  (2023, 37, 'Señale la respuesta correcta en relación a Streptococcus pneumoniae:', 'Existen 23 serotipos capsulares.', 'Produce beta-hemólisis en agar sangre.', 'Da positiva la prueba de solubilidad en bilis.', 'La resistencia a los betalactámicos está mediada por una betalactamasa.', NULL, 'c', NULL, NULL, NULL),
  (2023, 38, '¿Qué ectoparásito presenta el siguiente orden taxonómico: filo Arthropoda, clase Insecta, orden Diptera?:', 'Pediculus.', 'Sarcoptes.', 'Chrysomya.', 'Pulex.', NULL, 'c', NULL, NULL, NULL),
  (2023, 39, 'Paciente de 32 años, esplenectomizado, VIH positivo acude a urgencias por fiebre de 40ºC, cefalea y artralgias intensas de 72 horas de evolución. Refiere picadura de garrapatas. En el frotis de sangre periférica se observa la presencia de un microorganismo intraeritrocitario formando una imagen en forma de cruz (tétrada en la división del microorganismo) que resulta patognomónica. ¿A qué enfermedad corresponde?:', 'Enfermedad de Lyme.', 'Babesiosis.', 'Ehrlichiosis.', 'Anaplasmosis granulocítica humana.', NULL, 'b', NULL, NULL, NULL),
  (2023, 40, 'Paciente de 50 años procedente de Guinea Ecuatorial con dolor abdominal y diarrea de 8 días de evolución. En el estudio parasitológico se observan trofozoítos de Dientamoeba fragilis. No se aísla ningún otro patógeno. ¿Cuál sería el tratamiento de elección?:', 'Exclusivamente sintomático, no se recomienda en estos casos el uso de antimicrobianos.', 'Paromomicina 500 mg/8h oral.', 'Metronidazol 1 g oral, en dosis única.', 'Tinidazol 500 mg/8h oral.', NULL, 'b', NULL, NULL, NULL),
  (2023, 41, '¿Cómo se define el concepto de velocidad de disolución intrínseca?:', 'Velocidad de disolución de una formulación en comprimidos bajo la condición de mantenimiento constante del área superficial, evitando el uso de disgregantes.', 'Velocidad de disolución bajo la condición de mantenimiento de las propiedades intrínsecas de una sustancia amorfa.', 'Velocidad de disolución bajo la condición de mantenimiento de las propiedades intrínsecas de una sustancia cristalina.', 'Velocidad de disolución de una sustancia pura tras su compactación bajo la condición de mantenimiento constante del área superficial.', NULL, 'd', NULL, NULL, NULL),
  (2023, 42, '¿Qué repercusión práctica tiene que un preparado líquido o semisólido presente un comportamiento reológico dilatante?:', 'Que se dilata con el aumento de la temperatura, debiendo controlarse ésta a lo largo del proceso de mezcla.', 'Que se dilata con la disminución de la temperatura, debiendo controlarse ésta a lo largo del proceso de mezcla.', 'Que incrementa su viscosidad cuando se aumenta la velocidad o la fuerza de agitación en los tanques de mezcla.', 'Que disminuye su viscosidad cuando se aumenta la velocidad o fuerza de agitación en los tanques de mezcla.', NULL, 'c', NULL, NULL, NULL),
  (2023, 43, '¿Puede aplicarse una formulación en forma de polvos para administración cutánea sobre heridas abiertas o piel seriamente dañada?:', 'No. En ningún caso. El potencial efecto abrasivo de las mezclas pulverulentas es incompatible con la piel dañada.', 'Sí, pero sólo si el preparado final es estéril.', 'Sí, pero sólo si se presentan en envases presurizados adaptados para la aplicación cutánea.', 'Sí, siempre que el preparado posea propiedades bactericidas o bacteriostáticas contrastadas o incluya un conservante adecuado.', NULL, 'b', NULL, NULL, NULL),
  (2023, 44, '¿Cuál de los siguientes métodos es eficaz para la despirogenación de material de acondicionamiento primario constituyendo el método de referencia descrito en la Farmacopea Europea?:', 'Tratamiento por calor seco en condiciones mínimas de temperatura y tiempo de exposición de 180ºC durante 3 horas.', 'Tratamiento por calor húmedo en condiciones mínimas de temperatura y tiempo de exposición de 250ºC durante 5 horas.', 'Tratamiento por calor húmedo en condiciones mínimas de temperatura y tiempo de exposición de 180ºC durante 3 horas.', 'Tratamiento por calor seco en condiciones mínimas de temperatura y tiempo de exposición de 250ºC durante 5 horas.', NULL, 'a', NULL, NULL, NULL),
  (2023, 45, 'Los sistemas dispersos se componen de una sustancia dispersada en un medio dispersante. El aerosol niebla consiste en un sistema disperso coloidal con la siguiente composición:', 'Sustancia dispersada – gas; medio dispersante - líquido.', 'Sustancia dispersada – sólido; medio dispersante - líquido.', 'Sustancia dispersada – líquido; medio dispersante - gas.', 'Sustancia dispersada – gas; medio dispersante – sólido.', NULL, 'c', NULL, NULL, NULL),
  (2023, 46, 'Señale la respuesta FALSA en relación con las emulsiones:', 'El signo de la emulsión se selecciona en función de la vía de administración y, en general, de la aplicación a la que se destina.', 'Las emulsiones O/A producen cierto efecto oclusivo y disminuyen la evaporación del agua, por lo que son más eficaces para mantener la hidratación de la piel que las A/O.', 'Las emulsiones O/A permiten la incorporación de aromatizantes en la fase acuosa para mejorar sus características organolépticas.', 'Las emulsiones destinadas a su administración por vía intramuscular pueden ser de tipo A/O y O/A.', NULL, 'b', NULL, NULL, NULL),
  (2023, 48, 'El flujo sanguíneo coronario en reposo del ser humano alcanza un promedio de 250 mL/min. ¿Qué porcentaje del gasto cardíaco total representa aproximadamente?:', '1%.', '5%.', '10%.', '15%.', NULL, 'b', NULL, NULL, NULL),
  (2023, 49, 'Señale la continuación de la secuencia que sucede en el proceso de fototransducción del ojo (Luz  Rodopsina  Transducina  GMPc fosfosdiesteresa …):', 'Cierre de canales de K+  Despolarización.', 'Apertura de canales de Na+  Hiperpolarización.', 'Apertura de canales de Na+  Despolarización.', 'Cierre de canales de Na+  Hiperpolarización.', NULL, 'd', NULL, NULL, NULL),
  (2023, 50, 'La velocidad del flujo sanguíneo es directamente proporcional a la cuarta potencia del radio del vaso, lo que significa que, a mayor grosor, mayor flujo de sangre. Esta afirmación viene determinada por la ecuación o ley de:', 'Fick.', 'Frank-Starling.', 'Poiseuille.', 'Ohm.', NULL, 'c', NULL, NULL, NULL),
  (2023, 51, 'En cuanto a la clasificación de las fibras nerviosas, aquellas que conducen la temperatura son del grupo:', 'Ia.', 'Ib.', 'II.', 'III.', NULL, 'd', NULL, NULL, NULL),
  (2023, 52, 'Indique el tipo de células en las que se secreta el péptido inhibidor gástrico:', 'Células G.', 'Células I.', 'Células K.', 'Células S.', NULL, 'c', NULL, NULL, NULL),
  (2023, 53, '¿En la maduración eritroide, cuál de las siguientes células se encuentra entre el eritroblasto policromático y el reticulocito?:', 'Proeritroblasto.', 'Hematíe.', 'Eritroblasto ortocromático.', 'Eritroblasto basófilo.', NULL, 'c', NULL, NULL, NULL),
  (2023, 54, 'Respecto al sistema digestivo señale la respuesta correcta:', 'La colipasa es una enzima glucolítica.', 'La elastasa y la aminopeptidasa se activan por la tripsina.', 'Las principales enzimas lipolíticas son las dipeptidasas.', 'Las carboxipeptidasas A y B son endopeptidasas.', NULL, 'b', NULL, NULL, NULL),
  (2023, 55, '¿Cuál de los siguientes fenómenos favorece el desplazamiento a la derecha de la curva de disociación de oxígeno-hemoglobina?:', 'Aumento de la temperatura.', 'Aumento de pH.', 'Disminución de CO2.', 'Disminución de la concentración de 2,3di-fosfoglicerato (2,3-DPG).', NULL, 'a', NULL, NULL, NULL),
  (2023, 56, '¿Cuál de las siguientes sustancias produce una disminución del filtrado glomerular?:', 'Óxido nítrico.', 'Prostaglandinas.', 'Noradrenalina.', 'Angiotensina II.', NULL, 'c', NULL, NULL, NULL),
  (2023, 57, 'Las células de Sertoli secretan una proteína denominada:', 'Proteína de unión de testosterona (TBP).', 'Proteína de unión a andrógenos (ABP).', 'Proteína granular acrosómica (AGP).', 'Proteína de unión meiótica (MBP).', NULL, 'b', NULL, NULL, NULL),
  (2023, 58, '¿Cuál de los siguientes elementos deriva de la Unidad Formadora de Colonias Megacariocíticas (CFU-Meg)?:', 'Plaqueta.', 'Glóbulo rojo.', 'Linfocito.', 'Neutrófilo.', NULL, 'a', NULL, NULL, NULL),
  (2023, 59, 'El sistema multiplicador contracorriente del riñón consiste en el intercambio de agua e iones entre el intersticio renal y:', 'El filtrado del túbulo contorneado proximal.', 'La sangre de la red capilar peritubular.', 'La sangre de la parte recta.', 'El filtrado del asa de Henle.', NULL, 'd', NULL, NULL, NULL),
  (2023, 60, '¿Qué nombre reciben los granulocitos de tamaño aumentado e hipersegmentados?:', 'Megalocitos.', 'Células de Mott.', 'Centrocitos.', 'Pleocariocitos.', NULL, 'd', NULL, NULL, NULL),
  (2023, 61, '¿Cuál es la morfología eritrocitaria más común en sangre periférica en las anemias hemolíticas autoinmunes?:', 'Microcitosis e hipocromía.', 'Policromasia, esferocitos, esquistocitos y excepcionalmente algún eritroblasto aislado.', 'Policromasia, anisopoiquilocitosis y drepanocitos.', 'Macrocitosis y acantocitos.', NULL, 'b', NULL, NULL, NULL),
  (2023, 62, '¿Qué tipo de anemia es la Hemoglobinuria Paroxística Nocturna?:', 'Hemolítica congénita.', 'Hemolítica autoinmune.', 'Hemolítica adquirida.', 'Ferropénica secundaria.', NULL, 'c', NULL, NULL, NULL),
  (2023, 63, '¿Cuál es la vida media de un hematíe en condiciones fisiológicas?:', '30 días.', '60 días.', '120 días.', '150 días.', NULL, 'c', NULL, NULL, NULL),
  (2023, 64, '¿Qué hallazgo es típico de una Leucemia Mieloide Aguda con t(15;17)(q22;q12)?:', 'Trombocitosis.', 'Neutrofilia.', 'Leucopenia.', 'Poliglobulia.', NULL, 'c', NULL, NULL, NULL),
  (2023, 65, 'Un hemograma refleja número bajo de hematíes acompañado de macrocitosis y marcado aumento de hemoglobina. Al observar el frotis, los hematíes son normocíticos y normocromos pero forman acúmulos. ¿Qué situación causa este hallazgo?:', 'Déficit de hierro.', 'Crioaglutininas.', 'Anticoagulante EDTA.', 'Neoplasia mieloproliferativa tipo Policitemia Vera.', NULL, 'b', NULL, NULL, NULL),
  (2023, 66, 'Señale la opción correcta sobre el síndrome de HELLP:', 'Es un síndrome que cursa con neutropenia, pero no con hemólisis.', 'Su etiología se debe a una disfunción endotelial.', 'Los pacientes presentan una trombocitosis marcada.', 'Se ven afectados diversos órganos, como los pulmones o el corazón, pero no suele afectar al hígado.', NULL, 'b', NULL, NULL, NULL),
  (2023, 67, '¿Cuál de los siguientes mediadores se encuentra disminuido en el endotelio vascular en las primeras fases de la enfermedad cardiovascular?:', 'Óxido nítrico.', 'Noradrenalina.', 'Angiotensina II.', 'Endotelina.', NULL, 'a', NULL, NULL, NULL),
  (2023, 68, 'Señale la respuesta correcta en relación con el caso de un paciente que presenta unos niveles de potasio de 6,5 mEq/L (valores de referencia: 3,5-5 mEq/L):', 'El ciclosilicato de sodio y zirconio, que favorece la excreción del catión, es un intercambiador de potasio muy selectivo empleado en hiperpotasemias.', 'A diferencia de las hipopotasemias, el uso de gluconato cálcico no tendría interés, al no contrarrestar el calcio los efectos sobre las membranas celulares causados por el potasio.', 'La insulina es un fármaco que se usa para reducir el potasio de forma muy segura, ya que cuando este es superior a 5 mEq/L, no presenta efecto hipoglucemiante.', 'El uso de betabloqueantes resulta de interés en pacientes con potasio elevado, disminuyendo su concentración plasmática al favorecer su penetración en el citoplasma de las células.', NULL, 'a', NULL, NULL, NULL),
  (2023, 69, 'Un paciente varón de 75 años es diagnosticado por su cardiólogo de hipertensión pulmonar. ¿Cuál de las siguientes afirmaciones NO es cierta?:', 'Es probable que el paciente presente ganancia de peso debido a edema periférico.', 'Es posible diagnosticar una hipertensión pulmonar en este paciente sin que esté presente una enfermedad respiratoria de base.', 'Una de las opciones de tratamiento disponibles sería el uso de inhibidores de fosfodiesterasa-5 junto con agonistas del receptor de la endotelina.', 'Este paciente estuvo en África subsahariana hace 10 años; una posibilidad es que la hipertensión pulmonar que presenta sea secundaria a una infección por Schistosoma spp.', NULL, 'c', NULL, NULL, NULL),
  (2023, 70, 'BS es una mujer de 71 años que acude a la consulta de atención farmacéutica por estar utilizando alectinib para tratar su cáncer de pulmón estadio IV. ¿Cuál de las siguientes afirmaciones es cierta?:', 'Lo más probable es que esté usando alectinib porque presente una mutación en el exón 19 o 21 del gen EGFR.', 'La mutación “driver” de esta paciente se suele asociar a personas no fumadoras.', 'Como es un cáncer de pulmón estadio IV, el enfoque óptimo del tratamiento para lograr la completa curación de la enfermedad es realizar una resección pulmonar del tumor.', 'Si presentara un un cáncer de pulmón de tipo escamoso, correspondería a un subtipo de cáncer de pulmón microcítico.', NULL, 'b', NULL, NULL, NULL),
  (2023, 71, '¿Cuál de las siguientes enfermedades NO está causada por anticuerpos?:', 'Síndrome de neurotoxicidad asociada a células efectoras (ICANS).', 'Síndrome de Guillain-Barré.', 'Pénfigo vulgar.', 'Enfermedad de Graves.', NULL, 'a', NULL, NULL, NULL),
  (2023, 72, '¿Cuál de estos hallazgos NO es esperable encontrar en un paciente diagnosticado de síndrome de Liddle?:', 'Hipernatremia.', 'Hipertensión.', 'Acidosis metabólica.', 'Hipocalemia.', NULL, 'c', NULL, NULL, NULL),
  (2023, 73, 'CA se ha realizado un estudio genético. Mediante una reacción en cadena de la polimerasa (PCR) se ha detectado una expansión del triplete CTG en el cromosoma 19, con unas 60 repeticiones. ¿Con qué enfermedad podría estar relacionada dicha anomalía?:', 'Distrofia miotónica.', 'Corea de Huntington.', 'Distrofia muscular de Becker.', 'Distrofia muscular de Duchenne.', NULL, 'a', NULL, NULL, NULL),
  (2023, 74, 'Señale la respuesta correcta respecto a la encefalopatía de Wernicke:', 'Se produce debido al déficit de vitamina B3 en pacientes alcohólicos.', 'Es una fase más avanzada, irreversible y prolongada del síndrome de Korsakoff, el cual es una fase aguda que la precede.', 'Ante la sospecha de esta encefalopatía, lo primero que se recomienda es administrar suero glucosado, y, una vez finalizado, las vitaminas correspondientes.', 'Estar sometido a sesiones de hemodiálisis intermitente supone un factor de riesgo de padecerla.', NULL, 'd', NULL, NULL, NULL),
  (2023, 75, 'La hipofosfatemia ligada al cromosoma X es una enfermedad rara en la cual existen mutaciones que inducen la producción excesiva y descontrolada del factor de crecimiento de fibroblastos 23. Sabiendo que este factor reduce la expresión de los transportadores encargados de la reabsorción de fósforo en diversas localizaciones del organismo, y que reduce la expresión de la hidroxilasa renal de la vitamina D, ¿qué afirmación es correcta?:', 'La aparición de esta enfermedad en la niñez provoca osteoporosis como principal manifestación ósea.', 'Una de las complicaciones que pueden surgir de su tratamiento con dosis elevadas de sales de fosfato y de calcitriol es la nefrocalcinosis.', 'Debe administrarse colecalciferol como forma preferente de vitamina D para compensar el déficit de fosfato.', 'Una estrategia de tratamiento para compensar una hipofosfatemia refractaria a las medidas iniciales, es añadir al tratamiento dosis altas de sales de calcio.', NULL, 'b', NULL, NULL, NULL),
  (2023, 76, 'Acerca del cáncer de mama, señale la opción correcta:', 'Una paciente con un tumor que mide más de 50 mm, pero no se ha diseminado a los ganglios linfáticos axilares presenta un estadio IV.', 'La hormonoterapia adyuvante con tamoxifeno o inhibidores de la aromatasa está indicada en pacientes premenopáusicas, pero no posmenopáusicas, ya que en este segundo grupo la producción de estrógenos es mínima.', 'El subtipo luminal tiende a presentar niveles altos de expresión de receptores de estrógenos y/o de progesterona, pero no una sobreexpresión de la proteína HER2 (receptor-2 de factor de crecimiento epidérmico humano).', 'Las mutaciones BRCA1 y BRCA2 son patognomónicas del cáncer de mama.', NULL, 'c', NULL, NULL, NULL),
  (2023, 77, 'En cuanto al glaucoma, señale la opción correcta:', 'El uso de prostaglandinas tópicas varias veces al día es una estrategia más útil para disminuir la presión intraocular que emplear asociaciones de fármacos.', 'Para que se pueda establecer un diagnóstico de glaucoma, la presión intraocular debe estar siempre por encima de 21 mmHg.', 'Si se desarrolla un glaucoma agudo, lo más probable es que este sea de ángulo estrecho.', 'El aumento de la presión intraocular se debe fundamentalmente al aumento de producción de humor vítreo.', NULL, 'c', NULL, NULL, NULL),
  (2023, 78, '¿Cuál de los siguientes hallazgos sería más esperable en un paciente con colitis ulcerosa grave?:', 'Anemia que pudiese requerir necesidad de transfusión.', 'Desnutrición grave por malabsorción.', 'Elevación muy marcada de la procalcitonina en las heces.', 'Formación de fístulas perianales.', NULL, 'a', NULL, NULL, NULL),
  (2023, 79, 'El síndrome ASA-tríada o tríada de Samter se caracteriza por intolerancia a aspirina y a otros antiinflamatorios no esteroideos, la presencia de pólipos nasales y:', 'Artritis reumatoide.', 'Asma.', 'Lupus eritematoso sistémico con anticuerpos antinucleares.', 'Enfermedad de Alzheimer.', NULL, 'b', NULL, NULL, NULL),
  (2023, 80, 'Un paciente de 8 años y 30 kg de peso ingresa en la unidad de infecciosas con fiebre de 38 ºC y sospecha de bacteriemia generalizada. No tolera vía oral, por lo que se le prescribe sueroterapia de mantenimiento. ¿Cuál sería el volumen a administrar, así como el ritmo de infusión según el método de Holliday-Segar?: Volumen diario de mantenimiento: Peso 0-10 kg: 100 mL/kg. Peso 11-20 kg: 1.000 mL + 50 mL/kg por cada kg >10 kg Peso >20 kg: 1.500 mL + 20 mL/kg por cada kg >20 kg. Ritmo de infusión: Peso 0-10 kg: 4 mL/kg/h Peso 11-20 kg: 40 mL/h + 2 mL/kg/h por cada kg >10 kg Peso >20 kg: 60 mL/h + 1 mL/kg/h por cada kg >20 kg.', '2.100 mL; 88,5 mL/h.', '1.700 mL; 70 mL/h.', '1.500 mL; 62,5 mL/h.', '850 mL; 35 mL/h.', NULL, 'b', NULL, NULL, NULL),
  (2023, 81, 'Señale la respuesta INCORRECTA respecto a la enfermedad pulmonar obstructiva crónica (EPOC):', 'La deficiencia grave de alfa1antitripsina es un factor de riesgo para el desarrollo de la enfermedad.', 'El recuento de eosinófilos en sangre periférica se usa como biomarcador para determinar el tratamiento en exacerbaciones.', 'El tiotropio tiene una semivida más corta que el ipratropio, por lo que se administra 2 veces al día.', 'La triple terapia inhalada con un broncodilatador beta-agonista de larga duración, un broncodilatador antagonista muscarínico de larga duración y un corticoide, puede ser adecuada en determinados pacientes.', NULL, 'c', NULL, NULL, NULL),
  (2023, 82, 'Paciente con insomnio que no responde a las medidas de higiene y otros métodos conductuales. Tiene un patrón de sueño caracterizado por una latencia de inicio larga, sin experimentar ansiedad durante el día. ¿Cuál de los siguientes fármacos está más indicado para su tratamiento?:', 'Lorazepam.', 'Triazolam.', 'Flurazepam.', 'Clorazepato.', NULL, 'b', NULL, NULL, NULL),
  (2023, 83, 'Señale la respuesta INCORRECTA en relación con el caso de un paciente diagnosticado de meningoencefalitis criptococócica sin inmunodepresión concomitante, que presenta cefalea, fiebre, letargo, déficit sensorial y de memoria, paresia de pares craneales, deficiencia visual y signos meníngeos de varias semanas de evolución:', 'El tratamiento de inducción consiste en la combinación de anfotericina B liposomal y flucitosina debido a la sinergia de los fármacos.', 'La penetración de flucitosina en el líquido cefalorraquídeo produce un descenso rápido de la carga de criptococos.', 'El efecto adverso principal de la flucitosina es la toxicidad renal y los de la anfotericina B liposomal son la supresión de la médula ósea y la toxicidad hepática.', 'La prevención de la enfermedad criptocócica consiste en la administración de fluconazol oral en los pacientes de alto riesgo.', NULL, 'c', NULL, NULL, NULL),
  (2023, 84, 'Señale cuál de las siguientes asociaciones es INCORRECTA:', 'Ácido zoledrónico-tratamiento de la hipercalcemia tumoral.', 'Furosemida-tratamiento de la hipocalcemia.', 'Denosumab-inhibición del ligando de RANK (RANK-L).', 'Paricalcitol-tratamiento del hiperparatiroidismo secundario.', NULL, 'b', NULL, NULL, NULL),
  (2023, 85, 'Indique la relación correcta fármaco – mecanismo de acción:', 'Everólimus – inhibidor de la calcineurina.', 'Tacrólimus – inhibidor de la calcineurina.', 'Ciclosporina – inhibidor de la mTOR.', 'Azatioprina – inhibidor de la mTOR.', NULL, 'b', NULL, NULL, NULL),
  (2023, 86, '¿Cuál de los siguientes fármacos para el tratamiento de esclerosis múltiple es un modulador del receptor de la esfingosina-1-fosfato?:', 'Teriflunomida.', 'Dimetilfumarato.', 'Siponimod.', 'Alemtuzumab.', NULL, 'c', NULL, NULL, NULL),
  (2023, 87, '¿Cuál de los siguientes fármacos puede producir efectos teratógenos en el feto y tiene un plan de prevención de embarazo?:', 'Ácido fólico.', 'Acido valproico.', 'Colecalciferol.', 'Levotiroxina.', NULL, 'b', NULL, NULL, NULL),
  (2023, 88, 'Con respecto a la inmunoterapia, indique la respuesta correcta:', 'Los anticuerpos monoclonales bloqueadores de CTLA-4, PD-1 o PD-L1 se usan para disminuir la respuesta inmunitaria.', 'Ipilimumab es un anticuerpo monoclonal IgG1 humano que se une a CTLA-4 y fue el primer inhibidor del punto de verificación inmunitaria aprobado en España para el tratamiento del cáncer.', 'Nivolumab es un anticuerpo monoclonal IgG4 humano que se une a la proteína CDK4/6, favoreciendo el aumento de la respuesta inmunitaria.', 'Los efectos adversos de la inmunoterapia se tratan de la misma manera que los de la quimioterapia convencional.', NULL, 'b', NULL, NULL, NULL),
  (2023, 89, '¿Qué tratamiento sería más indicado prescribir a un paciente diagnosticado de asma grave no controlado con glucocorticoides inhalados (GCI) a dosis altas + agonista adrenérgico de acción larga (LABA) + montelukast, que además tiene dermatitis atópica refractaria?:', 'Dupilumab, ya que también tiene la indicación en ficha técnica para el tratamiento de la dermatitis atópica.', 'Reslizumab, ya que también tiene la indicación en ficha técnica para el tratamiento de la dermatitis atópica.', 'Bevacizumab, ya que también tiene la indicación en ficha técnica para el tratamiento de la dermatitis atópica.', 'Ocrelizumab, por su buen perfil de seguridad en pacientes con dermatitis atópica.', NULL, 'a', NULL, NULL, NULL),
  (2023, 90, 'Una paciente fumadora de 70 años padece psoriasis en placas de carácter moderado-grave. Ha fracasado el tratamiento con ciclosporina, metotrexato y PUVA. Simultáneamente es diagnosticada de tuberculosis pulmonar. ¿Cuál de las siguientes opciones de tratamiento es correcta?:', 'Deberá iniciar inmediatamente tratamiento con un fármaco inhibidor de la quinasa janus (JAK) debido a su mejor perfil de seguridad.', 'Deberá iniciar inmediatamente tratamiento con certolizumab ya que es el único anti-TNF que no está contraindicado en caso de tuberculosis activa.', 'Deberá realizar primero tratamiento para la tuberculosis y luego iniciar tratamiento para la psoriasis con un fármaco biológico, por ejemplo, adalimumab.', 'Deberá realizar profilaxis antituberculosa con isoniazida + rifampicina antes de iniciar un tratamiento biológico.', NULL, 'c', NULL, NULL, NULL),
  (2023, 91, 'Con relación al tratamiento de la enfermedad por el VIH, indique la asociación INCORRECTA:', 'Bictegravir – inhibidor de la integrasa.', 'Lamivudina – inhibidor de la transcriptasa inversa.', 'Cabotegravir – inhibidor de la proteasa.', 'Lopinavir – inhibidor de la proteasa.', NULL, 'c', NULL, NULL, NULL),
  (2023, 92, '¿Qué tratamiento estaría indicado prescribir a una paciente de 45 años diagnosticada de colitis ulcerosa, sin otras patologías de interés, que no está controlada con mesalazina y azatioprina?:', 'Galcanezumab.', 'Benralizumab.', 'Infliximab.', 'Ranibizumab.', NULL, 'c', NULL, NULL, NULL),
  (2023, 93, 'En el contexto de un paciente esplenectomizado, solicitan al servicio de Farmacia la dispensación de vacunas de bacterias encapsuladas como prevención de infecciones a las que estos pacientes son especialmente sensibles. ¿Cuál de las siguientes vacunas NO dispensaría?:', 'Vacuna antineumocócica.', 'Vacuna antimeningocócica.', 'Vacuna frente a Bordetella pertussis.', 'Vacuna frente a Haemophylus influenzae tipo B.', NULL, 'c', NULL, NULL, NULL),
  (2023, 94, 'Indique la relación INCORRECTA entre fármaco – utilidad terapéutica:', 'Suplementos de sulfato de cobre - enfermedad de Wilson.', 'Deferoxamina - intoxicación por hierro.', 'Vitamina B1 - alcoholismo crónico.', 'Vitamina B12 - anemia megaloblástica.', NULL, 'a', NULL, NULL, NULL),
  (2023, 95, '¿Cuál de los siguientes fármacos NO es un agente modificador de lípidos empleado para el tratamiento de la dislipemia?:', 'Alirocumab.', 'Inclisirán.', 'Evolocumab.', 'Ácido obeticólico.', NULL, 'd', NULL, NULL, NULL),
  (2023, 96, 'Indique la respuesta FALSA sobre Adotrastuzumab emtansina:', 'Es un anticuerpo conjugado.', 'Su diana de acción es Trop-2.', 'Uno de los posibles efectos adversos es la disfunción cardiaca.', 'DM1, el componente citotóxico de trastuzumab emtansina, se une a tubulina, provocando la detención del ciclo celular en la fase G2/M.', NULL, 'b', NULL, NULL, NULL),
  (2023, 97, 'Indique la respuesta verdadera sobre emicizumab:', 'Es un anticuerpo monoclonal biespecífico contra el factor VII y VIII.', 'Reemplaza la actividad del factor VII.', 'Está indicado en profilaxis de rutina de los episodios de sangrado en pacientes con hemofilia A.', 'La vía de administración de elección es la intramuscular.', NULL, 'c', NULL, NULL, NULL),
  (2023, 98, '¿Qué característica define a un fármaco agonista parcial?:', 'El efecto máximo que produce siempre es inferior al que produce un agonista puro en el sistema de estudio (órgano, organismo, etc.).', 'Su eficacia relativa (α) tiene un valor en torno a 1.', 'Sus efectos no pueden ser bloqueados por un fármaco antagonista competitivo del mismo receptor.', 'Su efecto farmacológico viene determinado por su afinidad al receptor.', NULL, 'a', NULL, NULL, NULL),
  (2023, 99, 'En relación al mecanismo de transporte de fármacos denominado difusión pasiva, ¿cuál de las siguientes afirmaciones es correcta?:', 'Se realiza mediante una proteína transportadora con consumo de energía.', 'La fracción ionizada de los fármacos es la que atraviesa membranas con mayor facilidad.', 'Se produce en contra de gradiente de concentración del fármaco.', 'Es el principal mecanismo de absorción de fármacos y sigue la ley de Fick.', NULL, 'd', NULL, NULL, NULL),
  (2023, 100, 'De las siguientes afirmaciones, ¿cuál caracteriza a la Kd (constante de disociación de un fármaco por su diana) ?:', 'Se corresponde con un valor de concentración del fármaco en estudio, que ocupa más de la mitad de los receptores.', 'Su valor depende del efecto que produzca el fármaco sobre su diana.', 'Su valor será menor cuanto mayor sea la afinidad del fármaco por el receptor.', 'Su valor es independiente de la pendiente según la representación gráfica de Scatchard.', NULL, 'c', NULL, NULL, NULL),
  (2023, 101, '¿Cuál de las siguientes dianas farmacológicas pertenece al grupo de receptores catalíticos o con actividad enzimática intrínseca?:', 'El receptor muscarínico para acetilcolina.', 'El receptor de GABA tipo A (GABAA).', 'El receptor de insulina.', 'Los receptores de esteroides.', NULL, 'c', NULL, NULL, NULL),
  (2023, 102, '¿Qué característica cumplen los receptores acoplados a proteínas G?:', 'Poseen actividad ATPasa intrínseca.', 'Poseen residuos de serina y treonina, susceptibles de ser fosforilados, proceso esencial en la señalización celular que median.', 'Están formados por cuatro subunidades: alfa, beta, gamma y zeta.', 'Actúan como receptores intracelulares para hormonas.', NULL, 'b', NULL, NULL, NULL),
  (2023, 103, 'En relación con la glucoproteína P (P-gp), ¿cuál de las siguientes opciones es correcta?:', 'La P-gp es uno de los principales mecanismos de introducción de xenobióticos en el sistema nervioso central.', 'La P-gp se encuentra sobreexpresada en algunas células neoplásicas.', 'La regulación a la baja de la expresión de esta proteína es responsable de la resistencia a algunos antitumorales.', 'Los polimorfismos genéticos de la P-gp que le confieren baja actividad dan lugar a una reducción de la absorción de algunos fármacos, como la digoxina.', NULL, 'b', NULL, NULL, NULL),
  (2023, 104, 'En relación con la carbamazepina, señale la opción INCORRECTA:', 'Los metabolizadores rápidos, portadores de algunos polimorfismos genéticos del CYP2D6, presentan mayor riesgo de reacciones adversas al fármaco.', 'Los portadores de algunos polimorfismos genéticos del antígeno leucocitario HLA-B presentan un riesgo aumentado de reacciones dermatológicas severas cuando son tratados con este fármaco.', 'Es un inductor del CYP3A4.', 'La semivida plasmática de la carbamazepina disminuye paulatinamente durante las etapas iniciales del tratamiento.', NULL, 'a', NULL, NULL, NULL),
  (2023, 105, 'En un sistema determinado, dos fármacos, A y B, poseen afinidad por un mismo receptor y actúan de forma simultánea. Si la eficacia intrínseca de B es menor que la de A, entonces:', 'B es antagonista competitivo de A.', 'A es antagonista no competitivo de B.', 'B es antagonista no competitivo de A.', 'A es antagonista funcional de B.', NULL, 'a', NULL, NULL, NULL),
  (2023, 106, '¿Cuál de los siguientes es un medicamento con mecanismo de acción agonista α1-adrenérgico?:', 'Oximetazolina.', 'Isoproterenol.', 'Salbutamol.', 'Dobutamina.', NULL, 'a', NULL, NULL, NULL),
  (2023, 107, 'En relación con los efectos hemodinámicos de los antagonistas de canales de calcio, seleccione la opción correcta:', 'El verapamilo es un vasodilatador más potente que las dihidropiridinas.', 'Todos los antagonistas de canales de calcio disminuyen la resistencia vascular coronaria.', 'Las dihidropiridinas producen un efecto directo inotrópico negativo a concentraciones más bajas de las que se necesitan para reducir la resistencia arteriolar.', 'Los antagonistas de canales de calcio disminuyen de forma indirecta la actividad simpática.', NULL, 'b', NULL, NULL, NULL),
  (2023, 108, '¿Cuál de los siguientes fármacos se une a un sitio de unión específico en el complejo macromolecular del receptor GABAA, distinto del usado por el neurotransmisor GABA para ejercer su acción?:', 'Sertralina.', 'Clorazepato.', 'Trazodona.', 'Citalopram.', NULL, 'b', NULL, NULL, NULL),
  (2023, 109, 'En relación con la extracción de principios activos a partir de material vegetal, considerando las características de solubilidad de los mismos, el empleo del método Soxhlet consiste en:', 'Añadir sobre la droga agua hirviendo y mantenerla así cierto tiempo.', 'Realizar una percolación sobre la droga.', 'Poner la droga en contacto con el disolvente durante un tiempo prolongado a temperatura ambiente.', 'Realizar una extracción continua con maceración y percolación.', NULL, 'd', NULL, NULL, NULL),
  (2023, 110, 'Indique cuál de las siguientes afirmaciones es cierta:', 'La vincamina es un diterpeno nitrogenado con acción antimitótica.', 'El paclitaxel/taxol se encuentra en la raíz de Taxus brevifolia.', 'La efedrina es un alcaloide que carece de nitrógeno heterocíclico.', 'La artemisinina es una lactona sesquiterpénica con propiedades antitusivas.', NULL, 'c', NULL, NULL, NULL),
  (2023, 111, '¿Cuál de las siguientes afirmaciones sobre Cynara scolymus es FALSA?:', 'Sus principios activos son ácidos fenólicos y ácidos orgánicos.', 'Tiene efecto antiemético.', 'Contiene también lactonas sesquiterpénicas, que le confieren sabor amargo.', 'Se utilizan extractos acuosos de la hoja por sus propiedades farmacológicas.', NULL, 'b', NULL, NULL, NULL),
  (2023, 112, 'Si queremos administrar en un paciente intubado un medicamento por una sonda transpilórica, debemos tener en cuenta que:', 'Un fármaco que precisa un proceso de descarboxilación en medio ácido para ser activo podría ver reducida su eficacia.', 'Los fármacos administrados de esta manera no sufren efecto de primer paso hepático, alcanzando concentraciones séricas más altas.', 'Se recomienda administrar medicamentos de liberación prolongada triturados para conseguir un efecto rápido.', 'La administración de presentaciones muy osmóticas puede dar lugar a efectos adversos importantes como íleo paralítico.', NULL, 'a', NULL, NULL, NULL),
  (2023, 113, 'Un paciente hematológico comienza profilaxis antifúngica con posaconazol. ¿Ante cuál de las siguientes interacciones con otros fármacos que recibe el paciente deberíamos estar alerta?:', 'Puede que sea necesario reducir la dosis de venetoclax ya que posaconazol es un potente inhibidor de CYP3A4.', 'La inducción de UGT1A1 que provoca posaconazol podría ocasionar la eliminación aumentada de edoxabán.', 'Utilizando una formulación intravenosa de posaconazol, evitaríamos sus interacciones farmacocinéticas.', 'Puede que sea necesario aumentar la dosis de posaconazol ya que tacrólimus es un inductor de CYP2C19.', NULL, 'a', NULL, NULL, NULL),
  (2023, 114, 'Elija cuál de las siguientes parejas fármaco-parámetro farmacocinético utilizaría para realizar una monitorización adecuada del tratamiento:', 'Amikacina - >80% de tiempo entre dosis con concentración superior a la concentración mínima inhibitoria (CMI).', 'Vancomicina - área bajo la curva (AUC)/CMI objetivo entre 400-600 mg*h/L.', 'Ceftazidima/avibactam - concentración pico > de 40 mcg/mL para determinar su eficacia.', 'Fosfomicina - concentración valle entre 20-40 mcg/mL para determinar su seguridad.', NULL, 'b', NULL, NULL, NULL),
  (2023, 115, 'AM va a iniciar tratamiento con capecitabina para tratar un carcinoma de colon. ¿Cuál de las siguientes acciones relacionadas con farmacogenética sería correcta?:', 'Pedir una determinación de mutaciones en el gen de la dihidropirimidina deshidrogenasa (DPD). En caso de demostrarse una disminución de la actividad de la enzima, podría recomendarse comenzar con una dosis reducida para evitar efectos adversos.', 'Pedir una determinación de mutaciones en el gen de la DPD. En caso de demostrarse una disminución de la actividad de la enzima, podría recomendarse comenzar con una dosis superior a la habitual para mantener la eficacia.', 'Pedir una determinación de mutaciones en el gen de la UDP glucuronosiltransferasa 1 A (UGT1A). En caso de demostrarse una disminución de la actividad de la enzima, podría recomendarse comenzar con una dosis reducida para evitar efectos adversos.', 'Pedir una determinación de mutaciones en el gen de la UGT1A. En caso de demostrarse una disminución de la actividad de la enzima, podría recomendarse comenzar con una dosis superior a la habitual para mantener la eficacia.', NULL, 'a', NULL, NULL, NULL),
  (2023, 116, 'Para un fármaco que presenta una tasa de extracción hepática alta (EH > 0,7), ¿qué afirmación sería cierta?:', 'En un paciente que desarrollase una insuficiencia cardiaca aguda, su aclaramiento hepático se vería reducido significativamente.', 'En un paciente que estuviera malnutrido, desarrollando hipoalbuminemia, su aclaramiento hepático se vería reducido significativamente.', 'En un paciente que presentase por algún motivo un aumento del flujo hepático, su tasa de extracción hepática también se vería incrementada significativamente.', 'En un paciente con que tomase rifampicina (inductor enzimático potente), desde hace 3 meses, su aclaramiento hepático se vería incrementado significativamente.', NULL, 'a', NULL, NULL, NULL),
  (2023, 117, '¿Cuáles son los principales parámetros que tienen influencia en Tmax (tiempo para alcanzar la concentración máxima de fármaco en plasma) tras su administración extravasal?:', 'Ka (constante de velocidad de absorción) y Ke (constante de velocidad de eliminación).', 'F (biodisponibilidad), Ka y Ke.', 'Dosis y F.', 'Vd (volumen de distribución), dosis y Ke.', NULL, 'a', NULL, NULL, NULL),
  (2023, 118, 'Un fármaco con estructura de antibiótico betalactámico como amoxicilina, se absorbe prioritariamente tras su administración oral por:', 'Transporte activo.', 'Difusión por poros.', 'Endocitosis.', 'Pares de iones.', NULL, 'a', NULL, NULL, NULL),
  (2023, 119, 'Se administra un antibiótico mediante infusión intravenosa a un paciente de 80 kg. La semivida plasmática de eliminación del fármaco es de 7 horas y el volumen de distribución representa el 25% del peso corporal. La Css (concentración de fármaco en el estado de equilibrio dinámico) es de 10 mcg/mL. ¿Cuál es la dosis de carga a administrar en bolo para alcanzar dicho nivel?:', '250 mg.', '130 mg.', '300 mg.', '200 mg.', NULL, 'd', NULL, NULL, NULL),
  (2023, 120, 'En el proceso de absorción de un fármaco puede aparecer farmacocinética no lineal en el caso siguiente:', 'Elevada solubilidad del fármaco a partir de la forma de dosificación, que resulta en un aumento del fármaco disuelto al aumentar la dosis.', 'Modificación del volumen urinario en el tiempo por efecto de la dosis.', 'Baja solubilidad del fármaco a partir de la forma de dosificación, con disminución de la fracción de fármaco disuelta al aumentar la dosis.', 'Saturación de los sistemas enzimáticos responsables del metabolismo del fármaco al incrementarse la dosis administrada.', NULL, 'c', NULL, NULL, NULL),
  (2023, 121, '¿Cuál de las siguientes afirmaciones es verdadera respecto a la farmacocinética del ácido valproico?:', 'La principal vía de metabolismo del fármaco es hepática por mecanismos de oxidación a través del citocromo CYP3A4.', 'La absorción oral del ácido valproico es errática por lo que su biodisponibilidad es menor al 50%.', 'La asociación con fenobarbital puede aumentar las concentraciones plasmáticas del fármaco por lo que aumenta el riesgo de toxicidad por ácido valproico.', 'El porcentaje de unión a proteínas plasmáticas depende de la concentración del fármaco, alcanzando un porcentaje de unión de aproximadamente el 90% a concentraciones plasmáticas mayores de 75 mcg/mL.', NULL, 'd', NULL, NULL, NULL),
  (2023, 122, 'En la siguiente imagen se representa el perfil concentración-tiempo de dos diferentes situaciones para un mismo fármaco de administración oral con proceso de absorción y eliminación siguiendo una cinética de orden uno. Siendo la dosis la misma para los dos casos y asumiendo que ambas situaciones presentan el mismo volumen de distribución (Vd) y biodisponibilidad (F), ¿qué parámetros farmacocinéticos son similares en los dos casos?:', 'Tiempo hasta alcanzar la concentración max (Tmax) y concentración máxima (Cmax).', 'Tiempo hasta alcanzar la concentración max (Tmax) y constante de absorción (Ka).', 'Constante de absorción (Ka) y semivida de eliminación (t1/2).', 'Semivida de eliminación (t1/2) y área bajo la curva (AUC).', NULL, 'd', NULL, NULL, 'sin_imagen'),
  (2023, 123, 'En cuanto a la degradación de los esqueletos carbonados de los aminoácidos, es cierto que:', 'La treonina es un ejemplo de aminoácido exclusivamente cetogénico.', 'El tetrahidrofolato y la S-adenosilmetionina son dos de los más importantes cofactores de enzimas que participan en la transferencia de grupos amino.', 'Los aminoácidos que provienen de la degradación de proteínas y acaban produciendo fumarato, se consideran cetogénicos.', 'En condiciones de ayuno, la leucina contribuye de manera importante a la cetosis.', NULL, 'd', NULL, NULL, NULL),
  (2023, 124, 'MLS es una paciente que requiere del uso de nutrición parenteral domiciliaria por presentar un síndrome de intestino corto postquirúrgico. ¿Qué elemento NO esperaría añadir a su nutrición parenteral, si no se conociesen más datos de la paciente?:', 'Calcio.', 'Bromo.', 'Zinc.', 'Magnesio.', NULL, 'b', NULL, NULL, NULL),
  (2023, 125, 'Señale la afirmación correcta con respecto a la ruta de las pentosas-fosfato:', 'En la fase oxidativa se produce la conversión de glucosa 6-P a ribulosa 5-P con obtención de 4 moléculas de NADPH.', 'La primera reacción de la fase no oxidativa consiste en la oxidación de glucosa 6-P a 6-fosfogluconolactona.', 'La enzima glucosa 6-fosfato deshidrogenasa cataliza la conversión de glucosa 6-P a 6-fosfogluconolactona. Los individuos con déficit de esta enzima tienen mayor susceptibilidad de infección por Plasmodium falciparum.', 'La primera reacción de la fase no oxidativa consiste en una reacción de epimerización.', NULL, 'd', NULL, NULL, NULL),
  (2023, 127, 'Las rutas de la glucólisis y de la gluconeogénesis resultan esenciales para el correcto funcionamiento del cuerpo humano. En relación a ellas, señale la opción verdadera:', 'De las 10 reacciones que tienen lugar en la glucólisis, 5 son comunes a la gluconeogénesis, pero realizándose en el sentido inverso.', 'La reacción catalizada por la fosfoglicerato quinasa durante la glucólisis es la primera del proceso que produce poder reductor en forma de NADH.', 'La fosforilación de la fructosa-6P en la posición 1 se ve favorecida por la presencia de fructosa 2,6-bifosfato.', 'La glucoquinasa es un tipo de hexoquinasa muy selectiva para la glucosa que se encuentra fundamentalmente en el músculo esquelético para optimizar la obtención de energía en este.', NULL, 'c', NULL, NULL, NULL),
  (2023, 128, '¿Cuál de las siguientes enzimas NO esperaríamos encontrar en un eritrocito?:', 'Lactato deshidrogenasa.', 'Fosfofructocinasa-1.', 'Piruvato deshidrogenasa.', 'Bisfosfoglicerato mutasa.', NULL, 'c', NULL, NULL, NULL),
  (2023, 129, 'La heparina es un glucosaminoglucano empleado habitualmente como anticoagulante. Actúa uniéndose a diversas proteínas plasmáticas, incluida la antitrombina III. ¿A cuál de los siguientes residuos aminoacídicos es más probable que se una la heparina?:', 'Lisina.', 'Serina.', 'Leucina.', 'Ácido glutámico.', NULL, 'a', NULL, NULL, NULL),
  (2023, 130, 'Alan Turing es uno de los personajes históricos más famosos que ha fallecido por ingesta de cianuro. ¿Cuál fue el principal mecanismo que produjo su muerte?:', 'Desacoplamiento de la fosforilación oxidativa y el transporte electrónico, de forma que se consume O2 pero no se sintetiza ATP.', 'Bloqueo de la cadena de transporte de electrones mitocondrial por inhibición potente del complejo IV (citocromo oxidasa).', 'Parálisis del ciclo de Krebs por la inhibición de la succinato deshidrogenasa, impidiendo que el succinil-CoA se pueda convertir en succinato.', 'Inhibición de la fosforilación oxidativa por bloqueo irreversible de la subunidad soluble de la ATP sintasa.', NULL, 'b', NULL, NULL, NULL),
  (2023, 131, 'Un paciente varón acaba de ser diagnosticado de una glucogenosis tipo 1 (enfermedad de Von Gierke). ¿Cuál de las siguientes afirmaciones le parece coherente con respecto a su diagnóstico?:', 'Es bastante probable que su descendencia presente esta misma patología, al estar ligada al sexo de forma dominante.', 'Se espera que los niveles de glucemia basal del paciente sean muy elevados por la hiperactivación de glucógeno fosforilasa que presenta.', 'Aunque prácticamente cualquier órgano puede verse afectado por esta patología, el principal defecto ocurre a nivel muscular.', 'Aunque se llame glucogenosis, la enzima afectada en esta patología actúa sobre unidades aisladas de glucosa, en forma de monosacárido.', NULL, 'd', NULL, NULL, NULL),
  (2023, 133, 'La síntesis de ADN se lleva a cabo de forma semiconservativa durante la replicación, y se caracteriza por:', 'Llevarse a cabo siempre en dirección 3’ → 5’ tanto en eucariotas como en procariotas.', 'Dar lugar a una molécula de ADN mediante la rotura de las hebras de origen que se reordenan de una forma intercalada de fragmentos nuevos y viejos.', 'Originar dos moléculas de ADN, cada una de ellas compuesta de una hebra del ADN original y de una hebra complementaria nueva.', 'Generar dos moléculas de ADN, donde cada molécula recién sintetizada está formada por dos cadenas de novo.', NULL, 'c', NULL, NULL, NULL),
  (2023, 134, 'Los cambios en el ADN codificante causados por sustituciones no silenciosas, en concreto por las mutaciones sin sentido:', 'Producen inserciones o deleciones de uno o más pares de bases que modifican en el marco de lectura de la proteína.', 'Tiene como efecto la aparición de un codón de terminación o de paro y como consecuencia, se provoca el cese prematuro de la traducción del ARNm y se obtiene una proteína acortada, truncada.', 'No están sometidos a la presión de selección evolutiva ni influyen en la susceptibilidad frente a enfermedades.', 'Producen un codón nuevo que codifica un aminoácido diferente y alteran la secuencia de aminoácidos en la proteína.', NULL, 'b', NULL, NULL, NULL),
  (2023, 135, 'El proceso de corte y empalme (splicing) del ARN es un proceso:', 'Post-transcripcional de maduración del ARN transcrito primario del cual eliminan intrones.', 'Que tiene lugar en los extremos 5'' de la cadena de ARN, pero no en los extremos 3''.', 'En el que los exones del transcrito primario son eliminados de forma secuencial y los intrones situados a cada lado de los sitios de empalme deben unirse.', 'Exclusivo del procesamiento del ARN ribosómico.', NULL, 'a', NULL, NULL, NULL),
  (2023, 136, 'En el análisis molecular de hibridación de los ácidos nucleicos mediante la técnica de hibridación in situ fluorescente pueden combinarse:', 'Cultivo celular y microscopía.', 'Southern-blot y autorradiografía.', 'PCR y secuenciación.', 'RT-PCR y electroforesis.', NULL, 'a', NULL, NULL, NULL),
  (2023, 137, 'La reparación por la escisión nucleotídica (NER, nucleotide excision repair) es un mecanismo que repara daños en el ADN que consiste en la:', 'Corrección de alteraciones que causan distorsión en la doble hélice, y eliminación de diversos daños voluminosos.', 'Reparación de daños por hidrólisis (desaminación o pérdida de base), oxidación por radicales libres de oxígeno, alquilación, y derivados no voluminosos.', 'Corrección de errores cometidos en la replicación o errores que la impiden.', 'Reparación de la rotura física del ADN que puede ocurrir por exposición a radiación ionizante.', NULL, 'a', NULL, NULL, NULL),
  (2023, 138, '¿Cuál de las siguientes enzimas NO está implicada en el proceso de modificación del extremo 5’ del ARN mensajero eucariótico que ocurre poco después de iniciarse la transcripción?:', 'Fosfatasa.', 'Guanililtransferasa.', 'Topoisomerasa.', 'Metilasa.', NULL, 'c', NULL, NULL, NULL),
  (2023, 139, 'El sistema que localiza emparejamientos incorrectos puede identificar cuál de las dos hebras de ADN es la parental, en función de:', 'El contenido en G+C de cada hebra.', 'La longitud de cada hebra.', 'La temperatura de fusión de cada hebra.', 'El grado de metilación de cada hebra.', NULL, 'd', NULL, NULL, NULL),
  (2023, 140, 'La supresión, en ciertos casos, de la expresión de uno de los dos alelos de un gen en cromosomas homólogos (ya sea de la madre o del padre) es un fenómeno conocido como:', 'Aneuploidía genómica.', 'Impronta genómica.', 'Recombinación genómica.', 'Silenciamiento génico.', NULL, 'b', NULL, NULL, NULL),
  (2023, 141, 'Una enzima de restricción es aquella que puede reconocer una secuencia característica de nucleótidos dentro de una molécula de ADN. En relación con esto, señale la respuesta FALSA de las siguientes opciones:', 'Los isoesquizómeros son dos enzimas con la misma secuencia de reconocimiento, aunque puede que no corten en la misma posición.', 'El ADN recombinante se obtiene mediante enzimas de restricción.', 'El corte de ADN se realiza a través de la ruptura de los enlaces fosfodiéster sólo en la hebra de cadena simple.', 'Corta el ADN en un punto en concreto o sito diana generando extremos romos y cohesivos.', NULL, 'c', NULL, NULL, NULL),
  (2023, 142, 'La utilidad de los valores de referencia basados en población de los biomarcadores se puede evaluar determinando:', 'El valor de discriminante.', 'El sesgo o inexactitud.', 'El índice de individualidad bioquímica.', 'La variabilidad biológica intersujetos.', NULL, 'c', NULL, NULL, NULL),
  (2023, 143, 'Para la cuantificación fiable del lactato en plasma, además de un anticoagulante, ¿qué otro aditivo debe estar presente?:', 'Un gel inerte separador del suero (SST).', 'Heparina de litio.', 'Piruvato.', 'Fluoruro sódico.', NULL, 'd', NULL, NULL, NULL),
  (2023, 144, '¿Qué prueba permite evaluar la permeabilidad de la barrera hematoencefálica?:', 'La relación de concentraciones de la albúmina en el líquido cefalorraquídeo frente a la albúmina sérica.', 'La detección de bandas oligoclonales de IgG mediante isoelectroenfoque.', 'La presión hidrostática tras la punción lumbar.', 'El índice de IgG.', NULL, 'a', NULL, NULL, NULL),
  (2023, 145, '¿Qué es la fracción delta de la bilirrubina o biliproteína?:', 'Es un polímero resultado de enlaces intermoleculares entre la bilirrubina mono y diconjugada.', 'Es la denominación actual de la bilirrubina no conjugada.', 'Es la bilirrubina no conjugada unida a la albúmina.', 'Es el precursor inmediato del urobilinógeno.', NULL, 'c', NULL, NULL, NULL),
  (2023, 146, '¿Qué grupo de parámetros bioquímicos en suero es el más afectado por los cambios posturales durante la toma de la muestra?:', 'Las proteínas séricas.', 'Los electrolitos mayoritarios (sodio, potasio y cloruro).', 'La creatinina y otros productos nitrogenados de desecho.', 'La glucosa y otros intermediarios metabólicos.', NULL, 'a', NULL, NULL, NULL),
  (2023, 147, 'La imagen adjunta muestra el proteinograma de suero de un paciente en estudio (caso) frente al de un control sano. ¿Cuál es la hipótesis diagnóstica más probable?:', 'Mieloma.', 'Gammapatía triclonal.', 'Síndrome nefrótico.', 'Deficiencia de alfa-1-antitripsina.', NULL, 'd', NULL, NULL, 'sin_imagen'),
  (2023, 148, '¿Cuál es el uso principal del antígeno carcinoembrionario (CEA) en el cáncer colorrectal?:', 'Barrido (screening) poblacional.', 'Diagnóstico definitivo.', 'Seguimiento de la evolución clínica.', 'Estadiaje del tumor.', NULL, 'c', NULL, NULL, NULL),
  (2023, 149, 'Si ingresase un paciente en la Unidad de Cuidados Intensivos de su hospital con sospecha de shock séptico, ¿cuál de las siguientes alteraciones NO se esperaría encontrar en su analítica?:', 'Elevación de la proteína C reactiva.', 'Disminución de la prealbúmina.', 'Disminución de la transferrina.', 'Disminución de la procalcitonina.', NULL, 'd', NULL, NULL, NULL),
  (2023, 150, 'Señale la afirmación verdadera en relación con el cáncer de próstata:', 'La localización más frecuente de afectación metastásica es el hueso, siendo en estos casos de ayuda diagnóstica encontrar niveles de fosfatasa ácida elevada y de fosfatasa alcalina disminuida.', 'La detección de un antígeno prostático específico (PSA) elevado se relaciona de manera muy específica, pero poco sensible, con un diagnóstico de adenocarcinoma de próstata.', 'En pacientes en tratamiento con inhibidores de 5-alfa-reductasa, los valores absolutos de PSA se ven reducidos, pudiendo ocasionar falsos negativos en la detección de adenocarcinoma si se toman como referencia los intervalos de PSA generales.', 'La alfa-fetoproteína es un marcador útil en el seguimiento de la progresión a enfermedad metastásica en pacientes con cáncer de próstata.', NULL, 'c', NULL, NULL, NULL),
  (2023, 151, 'La cuantificación del número de moles de analito en un tipo de volumetría puede llevarse a cabo electroquímicamente a través de la ley de Faraday de la electrolisis utilizando una técnica analítica electroquímica determinada. ¿De cuál se trata?:', 'Conductimetría.', 'Amperometría.', 'Culombimetría.', 'Potenciometría.', NULL, 'c', NULL, NULL, NULL),
  (2023, 152, '¿Cuál de los siguientes compuestos es un indicador metalocrómico comúnmente utilizado en las volumetrías de formación de complejos?:', 'Azul de bromotimol.', 'Verde de bromocresol.', 'Naranja de metilo.', 'Naranja de xilenol.', NULL, 'd', NULL, NULL, NULL),
  (2023, 153, 'Siendo ci y zi, respectivamente, la concentración y la carga de los iones presentes en una disolución, la fuerza iónica (I) de dicha disolución se calcula como:', '𝐼 ∑ 𝑐 𝑧 .', '𝐼 ∑ 𝑐 𝑧 .', '𝐼 ∑ 𝑐 𝑧 .', '𝐼 ∑ 𝑐 𝑧 .', NULL, 'd', NULL, NULL, NULL),
  (2023, 154, 'Teniendo en cuenta que los valores de pKa del ácido carbónico son: pKa1 (H2CO3) = 6,35; pKa2 (HCO3-) = 10,33, ¿qué puede afirmarse respecto al pH de una disolución 0,01 M de monohidrógeno carbonato de sodio (bicarbonato de sodio) ?:', 'Es menor de 3,0.', 'Está entre 3,0 y 5,0.', 'Está entre 6,0 y 10,0.', 'Es mayor de 10,0.', NULL, 'c', NULL, NULL, NULL),
  (2023, 155, 'Teniendo en cuenta que las constantes de formación metal-EDTA son: log Kf (HgY2-) = 21,7; log Kf (MgY2-) = 8,79, indique la afirmación correcta referente a una valoración complejométrica de una disolución de Hg2+ mediante el procedimiento de valoración por desplazamiento:', 'Se añade un exceso de EDTA como reactivo desplazante.', 'Se añade un exceso de Mg2+ como reactivo desplazante.', 'El magnesio liberado en la reacción de desplazamiento se valora con EDTA.', 'El EDTA liberado en la reacción de desplazamiento se valora con magnesio.', NULL, 'c', NULL, NULL, NULL),
  (2023, 156, 'El espectro recogido en la imagen, correspondiente al fármaco antidiabético tolbutamida, se ha obtenido mediante la siguiente técnica analítica:', 'Espectrometría de absorción ultravioleta-visible.', 'Espectrometría de absorción infrarroja.', 'Espectrometría de emisión atómica.', 'Espectrofotometría de absorción atómica.', NULL, 'b', NULL, NULL, 'sin_imagen'),
  (2023, 157, 'Un compuesto se disuelve primero en etanol y se registra su espectro de absorción. A continuación, dicho compuesto se disuelve en agua y se registra su espectro. A la vista de la figura, ¿qué efecto se observa en el máximo de absorción del compuesto en agua respecto a etanol?:', 'Hipercrómico.', 'Hipocrómico.', 'Batocrómico.', 'Hipsocrómico.', NULL, 'd', NULL, NULL, 'sin_imagen'),
  (2023, 158, '¿Cuál de estos detectores utilizados en cromatografía de líquidos mide una propiedad característica del soluto eluido de la columna?:', 'Conductimétrico.', 'Luz dispersada tras la evaporación.', 'Fluorimétrico.', 'Refractométrico.', NULL, 'c', NULL, NULL, NULL),
  (2023, 159, 'Se realiza la valoración fotométrica de un compuesto X con un agente valorador V para dar un producto P según la reacción X+V⥂P. Al representar la absorción frente al volumen de valorante añadido, la absorción se mantiene constante hasta el punto de equivalencia, comenzando a aumentar manteniendo una pendiente constante desde entonces. ¿Cuál de las siguientes afirmaciones es cierta?:', 'La única especie absorbente es el valorante.', 'La única especie absorbente es el analito.', 'Tanto el analito como el producto son especies absorbentes.', 'Tanto el analito como el valorante son especies absorbentes.', NULL, 'a', NULL, NULL, NULL),
  (2023, 160, 'La absorción de radiación infrarroja provoca cambios energéticos en la molécula que dan lugar a:', 'Únicamente cambios electrónicos.', 'Cambios eléctricos y electrónicos.', 'Únicamente cambios vibracionales.', 'Cambios vibracionales y rotacionales.', NULL, 'd', NULL, NULL, NULL),
  (2023, 161, 'Al comparar las estructuras químicas de bifenilo y fluoreno cabe esperar que la emisión de fluorescencia:', 'Sea mayor en el caso del fluoreno por tratarse de una estructura aromática y rígida.', 'Sea mayor en el caso del bifenilo debido a la presencia de dos anillos bencénicos.', 'Sea mayor en el caso del bifenilo debido a que la energía del segundo estado de singulete excitado es mayor que en el fluoreno.', 'Sea mayor en el caso del fluoreno debido a que la energía del segundo estado de singulete excitado es mayor que en el bifenilo.', NULL, 'a', NULL, NULL, NULL),
  (2023, 162, 'En la determinación analítica de elementos atómicos por espectrometría atómica de emisión en plasma, se logra una buena resolución de las líneas espectrales debido a:', 'Las elevadas temperaturas logradas en el seno del plasma.', 'Que con el plasma se trabaja en atmósfera inerte.', 'La elevada resolución de los selectores de doble red de difracción que poseen los equipos.', 'La elevada resolución de los selectores de doble filtro que poseen los equipos.', NULL, 'c', NULL, NULL, NULL),
  (2023, 163, 'El índice de retención de Kovats se utiliza en cromatografía de:', 'Líquidos y permite cuantificar solutos a partir de los cromatogramas.', 'Líquidos y permite identificar solutos a partir de los cromatogramas.', 'Gases y permite cuantificar solutos a partir de los cromatogramas.', 'Gases y permite identificar solutos a partir de los cromatogramas.', NULL, 'd', NULL, NULL, NULL),
  (2023, 164, 'Cuando se emplea ionización química, en el espectro de masas de un compuesto orgánico de masa molecular 226, el pico del ion molecular aparecerá a un valor de relación masa/carga (m/z) de:', '225, debido a la pérdida de un electrón del analito en la ionización.', '227, debido a la aceptación de un electrón por el analito en la ionización.', '226, debido a la transferencia de un protón al analito en la ionización.', '227, debido a la transferencia de un protón al analito en la ionización.', NULL, 'd', NULL, NULL, NULL),
  (2023, 165, 'Se está llevando a cabo la separación de dos solutos por cromatografía de líquidos (HPLC) mediante elución en fase inversa en una columna de octadecilsilano (C18) y una fase móvil metanol:agua 70:30. Tras modificar la composición de la fase móvil a metanol:agua 50:50, ¿qué comportamiento debe esperarse?', 'Una disminución del tiempo de retención de los dos solutos.', 'Un aumento del tiempo de retención de los dos solutos.', 'Una disminución de la anchura de los picos.', 'No se modifica ningún parámetro cromatográfico.', NULL, 'b', NULL, NULL, NULL),
  (2023, 166, 'Considerando la ecuación de van Deemter, la eficacia de la separación cromatográfica:', 'Aumenta al disminuir el tamaño de partícula porque este parámetro afecta al término B.', 'Aumenta al aumentar el tamaño de partícula porque este parámetro afecta al término B.', 'Aumenta al disminuir el tamaño de partícula porque este parámetro afecta al término A.', 'Aumenta al aumentar el tamaño de partícula porque este parámetro afecta al término A.', NULL, 'c', NULL, NULL, NULL),
  (2023, 167, 'El tiempo de vida medio en una reacción de orden 0 es:', 'Proporcional a la constante cinética de la reacción (k) e inversamente proporcional a la concentración inicial de reactivo [A0].', 'Independiente de la concentración inicial de reactivo [A0] e inversamente proporcional a la constate cinética de la reacción (k).', 'Proporcional a la concentración inicial de reactivo [A0] e inversamente proporcional a la constante cinética de la reacción (k).', 'Inversamente proporcional a la constante cinética de la reacción (k) e independiente de la concentración inicial de reactivo [A0].', NULL, 'c', NULL, NULL, NULL),
  (2023, 168, 'El tiempo requerido para que la difusión de un principio activo a través de una membrana alcance el estado estacionario es proporcional:', 'A la anchura promedio de la membrana <h> y el coeficiente de difusión (D).', 'Al cuadrado de la anchura promedio de la membrana <h2> e inversamente proporcional al coeficiente de difusión (D).', 'Al cuadrado de la anchura promedio de la membrana <h2> y al coeficiente de difusión (D).', 'A la anchura promedio de la membrana <h> e inversamente proporcional al cuadrado del coeficiente de difusión (D2).', NULL, 'b', NULL, NULL, NULL),
  (2023, 169, 'Una disolución diluida de un principio activo no volátil en un solvente da lugar a:', 'Un aumento en la presión de vapor del solvente.', 'Un aumento de la temperatura de congelación de la disolución.', 'Una disminución en el potencial químico del solvente.', 'La aparición de propiedades coligativas, que dependen de la naturaleza del solvente.', NULL, 'c', NULL, NULL, NULL),
  (2023, 170, 'En caso de sospecha de intoxicación por compuestos oxidantes, ¿qué tipo de prueba bioquímica puede resultar útil para confirmar el diagnóstico?:', 'Colinesterasa.', 'Metahemoglobina.', 'Glucosa.', 'Osmolaridad sérica.', NULL, 'b', NULL, NULL, NULL),
  (2023, 171, '¿Cuál es la respuesta correcta con respecto a la intoxicación por ciguatera?:', 'Se produce cuando el ser humano ingiere peces grandes que han acumulado la toxina.', 'Produce un envenenamiento amnésico tras la ingesta de mejillones.', 'Produce parálisis tras la picadura de algunas especies de pulpos venenosos.', 'Es una toxina producida por corales que produce obstrucción en las vías respiratorias.', NULL, 'a', NULL, NULL, NULL),
