  (2023, 181, 'Una de las terapias para el envenenamiento por metales pesados es la quelatoterapia. Los agentes que se utilizan con este propósito son:', 'Ligandos ambidentados.', 'Ligandos polidentados.', 'Ligandos lineales.', 'Ligandos monodentados.', NULL, 'b', NULL, NULL, NULL),
