  (2023, 207, '¿Cuál es la asociación correcta entre hormona y zona de la corteza suprarrenal donde se sintetiza?:', 'Aldosterona – zona fasciculada.', 'Dehidroepiandrosterona (DHEA) – zona estriada.', 'Cortisol – zona reticular.', 'Desoxicorticosterona – zona glomerular.', NULL, 'd', NULL, NULL, NULL),
  (2023, 208, '¿Qué ocurre cuando aumenta la prevalencia de una enfermedad detectada por una prueba diagnóstica con unos valores de sensibilidad y especificidad determinados?:', 'Que el valor predictivo positivo de la prueba disminuye.', 'Que disminuyen en valor absoluto los falsos negativos.', 'Que el valor predictivo negativo de la prueba disminuye.', 'No quedan afectados los valores predictivos de la prueba.', NULL, 'c', NULL, NULL, NULL),
