-- INSERT preguntas FIR 2023 (convocatoria FSE 2023, Farmacia)
-- Fuente: Cuaderno_2023_F_0_C.pdf + respuestas_2023.xlsx
-- Generado: 204 preguntas validas de 210 impresas (6 anuladas excluidas: 28, 47, 126, 132, 180, 190)
-- Preguntas 2, 10, 16, 122, 147, 156, 157, 175 dependen de una imagen/
-- estructura/figura no incluida en el material recibido: se cargan con
-- explicacion_calidad='sin_imagen', imagen_path NULL.
-- tema queda NULL: se clasificara en un paso posterior.

BEGIN;

DO $$
BEGIN
  IF EXISTS (SELECT 1 FROM public.preguntas WHERE "año" = 2023) THEN
    RAISE EXCEPTION 'Ya existen preguntas del año 2023 en la tabla preguntas — abortando para evitar duplicados.';
  END IF;
END $$;


COMMIT;

